import AppIntents

/// Shortcuts actions for the boost. They appear in the Shortcuts app, in
/// Spotlight and to Siri with no setup, through `MaxCandelaShortcuts` below.
///
/// **Only in the Xcode build.** The App Intents metadata the system reads is
/// generated by Xcode's `appintentsmetadataprocessor` build step; SwiftPM does
/// not run it, so under `swift run` these compile but Shortcuts never sees
/// them. Test in `dist/` or an Xcode build. The `maxcandela://` links work in
/// both.
///
/// Each action goes through `BoostAutomation`, so the licence gate and the
/// kill-switch rule are the menu's, not a second copy of them.
private struct BoostAutomationError: Error, CustomLocalizedStringResourceConvertible {
    let outcome: BoostOutcome
    var localizedStringResource: LocalizedStringResource { "\(outcome.message)" }
}

@MainActor
private func performBoostCommand(_ command: BoostCommand) async throws -> some IntentResult & ProvidesDialog {
    let outcome = await BoostAutomation.run(command)
    // Throwing stops the rest of a Shortcut, which is right when it asked for
    // the boost and could not have it.
    guard outcome.succeeded else { throw BoostAutomationError(outcome: outcome) }
    return .result(dialog: IntentDialog(stringLiteral: outcome.message))
}

struct TurnBoostOnIntent: AppIntent {
    static let title: LocalizedStringResource = "Turn Brightness Boost On"
    static let description = IntentDescription(
        "Raises your XDR display above the brightness macOS normally allows. Needs MaxCandela Pro or the free trial, and a display with HDR headroom.")
    static let openAppWhenRun = false

    @MainActor
    func perform() async throws -> some IntentResult & ProvidesDialog {
        try await performBoostCommand(.on)
    }
}

struct TurnBoostOffIntent: AppIntent {
    static let title: LocalizedStringResource = "Turn Brightness Boost Off"
    static let description = IntentDescription("Returns your display to its normal brightness.")
    static let openAppWhenRun = false

    @MainActor
    func perform() async throws -> some IntentResult & ProvidesDialog {
        try await performBoostCommand(.off)
    }
}

struct ToggleBoostIntent: AppIntent {
    static let title: LocalizedStringResource = "Toggle Brightness Boost"
    static let description = IntentDescription(
        "Switches the brightness boost on if it is off, and off if it is on.")
    static let openAppWhenRun = false

    @MainActor
    func perform() async throws -> some IntentResult & ProvidesDialog {
        try await performBoostCommand(.toggle)
    }
}

/// Zero-setup entries in Spotlight, Siri and the Shortcuts gallery. Every
/// phrase must contain the app name — Apple's rule, checked at build time.
struct MaxCandelaShortcuts: AppShortcutsProvider {
    static var appShortcuts: [AppShortcut] {
        AppShortcut(
            intent: ToggleBoostIntent(),
            phrases: ["Toggle \(.applicationName)", "Toggle the \(.applicationName) boost"],
            shortTitle: "Toggle Boost",
            systemImageName: "sun.max"
        )
        AppShortcut(
            intent: TurnBoostOnIntent(),
            phrases: ["Turn on \(.applicationName)", "Turn the \(.applicationName) boost on"],
            shortTitle: "Boost On",
            systemImageName: "sun.max.fill"
        )
        AppShortcut(
            intent: TurnBoostOffIntent(),
            phrases: ["Turn off \(.applicationName)", "Turn the \(.applicationName) boost off"],
            shortTitle: "Boost Off",
            systemImageName: "sun.min"
        )
    }
}
